// AUTO-GENERATED by Claude Code
// Purpose: the slash-command list over the chat box (ui.slash_menu, commands.SLASH). While
//          the box holds "/" and the start of a name (nothing after it), the list shows: typing filters
//          it, Up / Down move, Tab completes the name (ready for its text, if it takes any), Enter runs it, Escape closes the list. Running
//          is sending "/<name>" as the message; the server does the rest (State.submit_chat), so a
//          command typed in full without the list works the same. A slash command in the box is
//          coloured (blue if it exists, orange if not) and hovering the box says what it does.
(() => {
  const BOX = 'textarea[name="prompt"]';
  const menuOf = (box) => box.form && box.form.querySelector("[data-slash-menu]");
  const rowsOf = (menu) => [...menu.querySelectorAll("[data-slash]")];
  const isOpen = (menu) => menu && menu.classList.contains("is-open");
  const close = (menu) => menu && menu.classList.remove("is-open");

  const setActive = (menu, row) => {
    rowsOf(menu).forEach((other) => other.classList.toggle("is-active", other === row));
    if (row) row.scrollIntoView({ block: "nearest" });
  };

  // show the commands matching what is typed after the slash; closed when the box isn't "/name"
  const update = (box) => {
    const menu = menuOf(box);
    if (!menu) return;
    const typed = /^\/(\S*)$/.exec(box.value);
    if (!typed) return close(menu);
    const query = typed[1].toLowerCase();
    const shown = rowsOf(menu).filter((row) => {
      const hit = row.dataset.slash.includes(query) || (row.dataset.words || "").includes(query);
      row.hidden = !hit;
      return hit;
    });
    // names starting with what was typed come first
    const best = shown.find((row) => row.dataset.slash.startsWith(query)) || shown[0];
    menu.classList.add("is-open");
    menu.classList.toggle("is-empty", !shown.length);
    const active = shown.find((row) => row.classList.contains("is-active"));
    setActive(menu, active || best || null);
  };

  // space: leave one after the name, for a command that takes text (data-takes)
  const fill = (box, row, space = false) => {
    box.value = `/${row.dataset.slash}${space && row.dataset.takes ? " " : ""}`;
  };

  // -- colouring: a textarea can't colour part of its text, so while it starts with a slash command
  // its text is drawn again in a layer under it (the mirror, same font and box) and its own text is
  // made transparent (app.css .composer[data-slashing]; an attribute, since React rewrites the form's
  // class). The command is blue if it exists, orange if not; hovering the box says what it does
  // (what the list shows beside it).
  const escapeHtml = (text) => text.replace(/[&<>]/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[char]));
  const COPIED = ["font", "letterSpacing", "padding", "borderWidth", "lineHeight", "textAlign", "tabSize"];

  const colour = (box) => {
    const form = box.form;
    const mirror = form && form.querySelector("[data-slash-mirror]");
    if (!mirror) return;
    const typed = /^\/(\S*)/.exec(box.value);
    // "@" mentions of variables are coloured in the same layer (assets/mentions.js paints them)
    const mentions = window.paintMentions || ((text) => ({ html: escapeHtml(text), found: false }));
    const painted = mentions(typed ? box.value.slice(typed[0].length) : box.value, escapeHtml);
    form.toggleAttribute("data-slashing", Boolean(typed) || painted.found);
    if (!typed && !painted.found) {
      box.title = "";
      mirror.textContent = "";
      return;
    }
    const menu = menuOf(box);
    const row = typed && menu && rowsOf(menu).find((other) => other.dataset.slash === typed[1].toLowerCase());
    const style = getComputedStyle(box);
    COPIED.forEach((name) => { mirror.style[name] = style[name]; });
    mirror.style.left = `${box.offsetLeft}px`;
    mirror.style.top = `${box.offsetTop}px`;
    mirror.style.width = `${box.offsetWidth}px`;
    mirror.style.height = `${box.offsetHeight}px`;
    const command = typed ? `<span class="slash-token${row ? "" : " is-unknown"}">${escapeHtml(typed[0])}</span>` : "";
    // the trailing space keeps a last empty line as tall as the box's
    mirror.innerHTML = `${command}${painted.html} `;
    mirror.scrollTop = box.scrollTop;
    box.title = !typed ? "" : row ? `${typed[0]} · ${row.dataset.about}` : `${typed[0]} isn't a command`;
  };

  document.addEventListener("input", (event) => {
    if (!(event.target instanceof Element) || !event.target.matches(BOX)) return;
    update(event.target);
    colour(event.target);
  });
  document.addEventListener("scroll", (event) => {
    if (event.target instanceof Element && event.target.matches(BOX)) colour(event.target);
  }, true);
  // sending empties the box without an input event
  const recolour = (form) => {
    const box = form instanceof Element && form.querySelector(BOX);
    if (!box) return;
    setTimeout(() => colour(box), 0);
    setTimeout(() => colour(box), 150);
  };
  document.addEventListener("reset", (event) => recolour(event.target), true);
  window.addEventListener("resize", () => document.querySelectorAll(BOX).forEach(colour));
  // assets/mentions.js: the variables changed, so what counts as a mention did
  window.recolourChatBox = () => document.querySelectorAll(BOX).forEach(colour);
  // State.submit_chat: a message that wasn't sent (an "@" method call was refused) goes back in the
  // box, to fix. After the form's own reset, which empties it
  window.restoreChatBox = (text) => setTimeout(() => {
    const box = document.querySelector(BOX);
    if (!box || box.value) return;
    box.value = text;
    box.focus();
    colour(box);
  }, 80);

  // capture phase: before the box's own Enter (send) and the page's Escape
  document.addEventListener("keydown", (event) => {
    const box = event.target;
    if (!(box instanceof Element) || !box.matches(BOX)) return;
    const menu = menuOf(box);
    if (!isOpen(menu)) return;
    const shown = rowsOf(menu).filter((row) => !row.hidden);
    const active = shown.find((row) => row.classList.contains("is-active"));
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      event.stopPropagation();
      if (!shown.length) return;
      const next = shown.indexOf(active) + (event.key === "ArrowDown" ? 1 : -1);
      setActive(menu, shown[(next + shown.length) % shown.length]);
    } else if (event.key === "Tab") {
      event.preventDefault();
      event.stopPropagation();
      if (active) fill(box, active, true);
      update(box);
      colour(box);
    } else if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      close(menu);
    } else if (event.key === "Enter" && !event.shiftKey) {
      // the picked command's full name is what gets sent; the box's own Enter then sends it
      if (active) fill(box, active);
      close(menu);
    }
  }, true);

  // mousedown, not click: the box keeps the focus
  document.addEventListener("mousedown", (event) => {
    const row = event.target instanceof Element && event.target.closest("[data-slash-menu] [data-slash]");
    if (!row) return;
    event.preventDefault();
    const box = row.closest("form").querySelector(BOX);
    fill(box, row);
    close(menuOf(box));
    box.form.requestSubmit();
  });

  // leaving the box, or sending, closes the list
  document.addEventListener("focusout", (event) => {
    if (event.target instanceof Element && event.target.matches(BOX)) close(menuOf(event.target));
  });
  document.addEventListener("submit", (event) => {
    if (event.target instanceof Element) close(event.target.querySelector("[data-slash-menu]"));
    recolour(event.target);
  });
})();
